SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);Alarm(100);tt:=Cputime();A:=JH(54,[17]);assert Dimension(A)eq 10;rows:=[* *];gg:=0;for p in[5,7,11,13]do f:=FrobeniusPolynomial(A,p);if Type(f)eq SeqEnum then f:=&*f;end if;assert Degree(f)eq 20;n:=Integers()!Evaluate(f,1);gg:=GCD(gg,n);Append(~rows,[*p,Coefficients(f),n*]);print "D31B_C54_Y10_ORDER",p,n,gg,Cputime(tt);end for;Write("work/deg10/continuation_20261031b/C54/Y10_orders.m",Sprint([*rows,gg,Factorization(gg)*]):Overwrite:=true);print "D31B_C54_Y10_ORDER_GCD_COMPLETE",gg,Factorization(gg),Cputime(tt);quit;
